  local segmentedUnits = ROAD100_SEGMENTED_CORRIDOR
      && ("road100Segmented" in plan) && plan.road100Segmented;
  local graphUnits = ROAD100_PAX_GRAPH_BRIDGE
      && ("road100Graph" in plan) && plan.road100Graph;
