  if (convertLongUnits) candidate.road100LongUnits <- true;
  if (ROAD100_PAX_PRODUCER_UNITS) candidate.road100PaxProducerUnits <- true;
  if (("road100MultiCatchment" in preliminary) && preliminary.road100MultiCatchment)
